import resume from '../data/resume.json'

const el = (tag, className, text) =>
{
    const node = document.createElement(tag)
    if (className) node.className = className
    if (text) node.textContent = text
    return node
}

/**
 * Projects
 * Each card shows the project's poster (made by `npm run posters`) and links to
 * its own page (generated by plugins/projectPages.js), where the reel plays
 */
const createProject = (project) =>
{
    const card = el('a', 'project-card')
    card.href = `/projects/${project.slug}/`

    const media = el('div', 'project-media')
    if (project.media)
    {
        const poster = el('img')
        poster.src = `/posters/${project.slug}.webp`
        poster.alt = ''
        poster.loading = 'lazy'
        poster.decoding = 'async'
        media.append(poster)
    }
    card.append(media)

    card.append(el('h3', null, project.name))
    if (project.description) card.append(el('p', 'project-meta', project.description))

    return card
}

/**
 * Experience
 */
const createExperience = (experience) =>
{
    const item = el('li', 'experience')
    item.append(el('p', 'experience-period', experience.period))

    const body = el('div')
    const heading = el('h3', null, experience.role)
    heading.append(el('span', 'experience-company', ` — ${experience.company}`))
    body.append(heading)

    if (experience.bullets?.length)
    {
        const bullets = el('ul')
        for (const bullet of experience.bullets) bullets.append(el('li', null, bullet))
        body.append(bullets)
    }

    item.append(body)
    return item
}

// resume.json is ordered oldest first; show the most recent work at the top
document.querySelector('.project-grid').append(...[...resume.projects].reverse().map(createProject))
document.querySelector('.experience-list').append(...[...resume.experiences].reverse().map(createExperience))
